def judge(base_req, base_err, can_req, can_err, base_p99, can_p99):
    b, c = base_err / base_req, can_err / can_req
    if can_req < 500:
        return "보류: 표본 부족"
    if c > b * 2 and c - b > 0.001:
        return f"롤백: 오류율 {c:.2%} > 기존 {b:.2%}의 2배"
    if can_p99 > base_p99 * 1.2:
        return f"롤백: p99 {can_p99}ms > 기존 {base_p99}ms × 1.2"
    return "통과: 전체 배포로"

print(judge(120000, 60, 300, 1, 180, 190))   # 보류: 표본 부족
print(judge(120000, 60, 4000, 9, 180, 185))  # 롤백: 오류율 0.22% > 기존 0.05%의 2배
print(judge(120000, 60, 4000, 2, 180, 240))  # 롤백: p99 240ms > 기존 180ms × 1.2
print(judge(120000, 60, 4000, 2, 180, 190))  # 통과: 전체 배포로

buckets = [(0.05, 9200), (0.1, 9700), (0.25, 9930), (0.5, 9985), (1.0, 9998), (float("inf"), 10000)]
def quantile(q, b):
    rank = q * b[-1][1]
    prev_le, prev_c = 0.0, 0
    for le, c in b:
        if c >= rank:
            if le == float("inf"):
                return prev_le
            return prev_le + (le - prev_le) * (rank - prev_c) / (c - prev_c)
        prev_le, prev_c = le, c
print(f"p50 {quantile(0.5, buckets)*1000:.0f}ms · p99 {quantile(0.99, buckets)*1000:.0f}ms")
# p50 27ms · p99 230ms
